9	 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/item-variant/item-attributes.jsx
10	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
11	 * plan step 2.1). Zero functional diff beyond the TypeScript annotations below, the
12	 * `useItemVariant` import path rewrite (see next paragraph), and a temporary `[overrides]`
13	 * console.log marker (verified live, then removed). The `<Stack spacing={1.5} flex={1} {...props}>` defaults-then-spread prop
14	 * order is preserved exactly, unchanged from base.
15	 *
16	 * The base file imports `useItemVariant` from the SFCC package path
17	 * (`@salesforce/retail-react-app/app/components/item-variant`) — inconsistent with its own three
18	 * siblings (item-image/item-name/item-price), which all already import it via the relative `'.'`.
19	 * Since `item-variant/index.tsx` is itself being overridden in this same commit,
20	 * this import is rewritten to match its siblings (`'.'`) per
21	 * .claude/rules/overrideStyling.md's "Importing an already-overridden component from a new
22	 * component" — a base-path import here would silently exercise the base `useItemVariant`/context
23	 * in Storybook and Vitest instead of this override.
24	 *
25	 * `useCurrentBasket` (from the SFCC hooks path) and the `useCurrency`/`app/hooks` barrel are not
26	 * overridden anywhere in this repo (verified by directory listing at time of writing — no
27	 * overrides/app/hooks/use-current-basket.ts, no overrides/app/hooks/index.ts), so both stay on
28	 * the base `@salesforce/retail-react-app/...` path.
29	 */
30	import React from 'react';
31	import { useIntl, FormattedMessage, FormattedNumber } from 'react-intl';
32	import { Flex, Stack, Text, Box } from '@salesforce/retail-react-app/app/components/shared/ui';
33	import { useItemVariant } from '.';
34	import PromoPopover from '@salesforce/retail-react-app/app/components/promo-popover';
35	import { useCurrency } from '@salesforce/retail-react-app/app/hooks';
36	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
37	import { usePromotions, useProducts, useProduct } from '@salesforce/commerce-sdk-react';
38	import { getDisplayVariationValues } from '@salesforce/retail-react-app/app/utils/product-utils';
39	
40	// See index.tsx's own note on why this is `any` rather than a structural type.
41	type SfccVariant = any;
42	
43	type ItemAttributesProps = {
44	  includeQuantity?: boolean;
45	  currency?: string;
46	  excludeBonusLabel?: boolean;
47	  hideAttributeLabels?: boolean;
48	} & Record<string, any>;
49	
50	/**
51	 * In the context of a cart product item variant, this component renders a styled
52	 * list of the selected variation values as well as any promos (w/ info popover).
53	 */
54	const ItemAttributes = ({
55	  includeQuantity,
56	  currency,
57	  excludeBonusLabel,
58	  hideAttributeLabels = false,
59	  ...props
60	}: ItemAttributesProps) => {
61	  const variant: SfccVariant = useItemVariant();
62	  const { data: basket } = useCurrentBasket();
63	  const { currency: activeCurrency } = useCurrency();
64	  const promotionIds = variant.priceAdjustments?.map((adj: SfccVariant) => adj.promotionId) ?? [];
65	  const intl = useIntl();
66	
67	  const displayBonusProductLabel = !excludeBonusLabel && variant?.bonusProductLineItem;
68	
69	  // Fetch all the promotions given by price adjustments. We display this info in
70	  // the promotion info popover when applicable.
71	  const { data: res } = usePromotions(
72	    {
73	      parameters: {
74	        ids: promotionIds.join(','),
75	      },
76	    },
77	    {
78	      enabled: promotionIds.length > 0,
79	    },
80	  );
81	  const promos = res?.data || [];
82	  const variationValues = getDisplayVariationValues(variant?.variationAttributes, variant?.variationValues);
83	
84	  // get variant info for bundled products in cart page and order history page
85	  const productBundleIds = variant?.bundledProductItems?.map(({ productId }: SfccVariant) => productId).join(',') ?? '';
86	  const { data: productBundleVariantData, isLoading: bundleVariantIsLoading } = useProducts(
87	    {
88	      parameters: {
89	        ids: productBundleIds,
90	        allImages: false,
91	      },
92	    },
93	    {
94	      enabled: Boolean(variant?.type?.bundle && productBundleIds),
95	      select: (result: SfccVariant) => {
96	        // formats response so we can easily display child quantity/variant selection
97	        return result?.data?.map((item: SfccVariant) => {
98	          const quantity = variant?.bundledProductItems.find(
99	            (childProduct: SfccVariant) => childProduct.productId === item.id,
100	          )?.quantity;
101	          return {
102	            ...item,
103	            quantity,
104	            variationValues: getDisplayVariationValues(item?.variationAttributes, item?.variationValues),
105	          };
106	        });
107	      },
108	    },
109	  );
110	
111	  // get bundle product data for wishlist page
112	  const { data: productBundleData, isLoading: productBundleIsLoading } = useProduct(
113	    {
114	      parameters: {
115	        id: variant?.id,
116	        allImages: false,
117	      },
118	    },
119	    {
120	      enabled: Boolean(variant?.type?.bundle && !productBundleIds),
121	    },
122	  );
123	
124	  return (
125	    <Stack spacing={1.5} flex={1} {...props}>
126	      {displayBonusProductLabel && (
127	        <Text lineHeight={1} color="black.600" fontSize="sm">
128	          <FormattedMessage defaultMessage="Bonus Product" id="item_attributes.label.bonus_product" />
129	        </Text>
130	      )}
131	
132	      {variationValues &&
133	        Object.keys(variationValues).map((key) => (
134	          <Text lineHeight={1} color="gray.700" fontSize="sm" key={`${key}: ${variationValues[key]}`}>
135	            {hideAttributeLabels ? variationValues[key] : `${key}: ${variationValues[key]}`}
136	          </Text>
137	        ))}
138	
139	      {includeQuantity && (
140	        <Text lineHeight={1} color="gray.700" fontSize="sm">
141	          <FormattedMessage
142	            defaultMessage="Quantity: {quantity}"
143	            values={{ quantity: variant.quantity }}
144	            id="item_attributes.label.quantity"
145	          />
146	        </Text>
147	      )}
148	
149	      {!productBundleIsLoading && productBundleData && !productBundleVariantData && (
150	        <Box>
151	          {/* Deviation from the base file (same labelled-comment convention as
152	                        product-view/index.tsx:659-661/1019-1022): added `?.` before `.map` —
153	                        `bundledProducts` is itself optional on the SDK's real Product type even
154	                        once `productBundleData` is truthy, which strict null checks catches and
155	                        the base file's plain JS did not need to guard against. This is a real,
156	                        narrow behaviour difference from base, not a pure typing satisfier: base
157	                        would throw here if `bundledProducts` were ever undefined on an otherwise
158	                        truthy `productBundleData`; this renders nothing instead. Directionally
159	                        safer (crash -> silent no-render), so left as-is rather than reverted to
160	                        match base's crash-on-that-shape behaviour exactly. */}
161	          {productBundleData?.bundledProducts?.map(({ product, quantity }: SfccVariant) => (
162	            <Box marginTop={2} key={product.id}>
163	              <Text fontSize="sm" color="gray.700" as="b">
164	                {product?.name}
165	              </Text>
166	              <Text fontSize="sm" color="gray.700">
167	                {intl.formatMessage({
168	                  defaultMessage: 'Qty',
169	                  id: 'add_to_cart_modal.label.quantity',
170	                })}
171	                : {quantity}
172	              </Text>
173	            </Box>
174	          ))}
175	        </Box>
176	      )}
177	
